static bool ReadAndClosed(string key, string expected)
{
    LocalReader.Reset();
    return Practice.ReadText(key) == expected && LocalReader.Opened == 1 && LocalReader.Closed == 1;
}
static bool FailedAndClosed()
{
    LocalReader.Reset();
    try { Practice.ReadText("broken"); return false; }
    catch (FormatException error) { return error.Message == "Unreadable text." && LocalReader.Opened == 1 && LocalReader.Closed == 1; }
}
